package com.physiovertex.app

import android.app.Activity
import android.os.Bundle
import android.graphics.Color
import android.graphics.Typeface
import android.text.InputType
import android.view.Gravity
import android.widget.*
import java.text.SimpleDateFormat
import java.util.*

class MainActivity : Activity() {
    private val blue = Color.rgb(24,92,180)
    private val prefs by lazy { getSharedPreferences("physiovertex", MODE_PRIVATE) }
    private lateinit var root: LinearLayout
    private var currentEmployee = "PV001"
    override fun onCreate(savedInstanceState: Bundle?) { super.onCreate(savedInstanceState); if(!prefs.contains("emp_PV001_pass")) prefs.edit().putString("emp_PV001_name","Employee 1").putString("emp_PV001_pass","1234").putString("emp_PV001_salary","0").apply(); showRoleScreen() }
    private fun base():LinearLayout{val s=ScrollView(this);root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(48,56,48,56);setBackgroundColor(Color.rgb(245,249,255))};s.addView(root);setContentView(s);return root}
    private fun title(t:String)=TextView(this).apply{text=t;textSize=28f;setTextColor(blue);setTypeface(null,Typeface.BOLD);gravity=Gravity.CENTER;setPadding(0,20,0,28)}
    private fun label(t:String)=TextView(this).apply{text=t;textSize=17f;setTextColor(Color.DKGRAY);setPadding(4,14,4,8)}
    private fun edit(h:String,p:Boolean=false)=EditText(this).apply{hint=h;if(p)inputType=InputType.TYPE_CLASS_TEXT or InputType.TYPE_TEXT_VARIATION_PASSWORD}
    private fun button(t:String,a:()->Unit)=Button(this).apply{text=t;textSize=17f;setTextColor(Color.WHITE);setBackgroundColor(blue);setOnClickListener{a()}}
    private fun space()=Space(this).apply{layoutParams=LinearLayout.LayoutParams(1,22)}
    private fun employeeIds()=prefs.all.keys.filter{it.startsWith("emp_")&&it.endsWith("_pass")}.map{it.removePrefix("emp_").removeSuffix("_pass")}.distinct().sorted()
    private fun showRoleScreen(){val v=base();v.addView(title("PhysioVertex v4.1"));v.addView(button("EMPLOYEE LOGIN"){showEmployeeLogin()});v.addView(space());v.addView(button("ADMIN LOGIN"){showAdminLogin()})}
    private fun showEmployeeLogin(){val v=base();v.addView(title("Employee Login"));val id=edit("Employee ID");val p=edit("Password",true);v.addView(id);v.addView(p);v.addView(button("LOGIN"){val e=id.text.toString().trim().uppercase(Locale.getDefault());if(prefs.getString("emp_${e}_pass",null)==p.text.toString()){currentEmployee=e;showEmployeeDashboard()}else Toast.makeText(this,"Invalid Employee ID or Password",Toast.LENGTH_SHORT).show()});v.addView(button("BACK"){showRoleScreen()})}
    private fun showAdminLogin(){val v=base();v.addView(title("Admin Login"));val id=edit("Admin ID");val p=edit("Password",true);v.addView(id);v.addView(p);v.addView(label("Default: ADMIN / 2468"));v.addView(button("LOGIN"){if(id.text.toString().trim().equals("ADMIN",true)&&p.text.toString()=="2468")showAdminDashboard() else Toast.makeText(this,"Invalid Admin Login",Toast.LENGTH_SHORT).show()});v.addView(button("BACK"){showRoleScreen()})}
    private fun showAdminDashboard(){val v=base();v.addView(title("Admin Dashboard v4.1"));v.addView(button("MY EMPLOYEE DASHBOARD"){currentEmployee="PV001";showEmployeeDashboard()});v.addView(space());v.addView(button("ADD / UPDATE EMPLOYEE"){showEmployeeEditor()});v.addView(space());v.addView(button("EMPLOYEE LIST / DELETE"){showEmployeeList()});v.addView(space());v.addView(button("ATTENDANCE OVERVIEW"){showAdminAttendance()});v.addView(space());v.addView(button("LEAVE REQUESTS"){showAdminLeaves()});v.addView(space());v.addView(button("LOGOUT"){showRoleScreen()})}
    private fun showEmployeeEditor(){val v=base();v.addView(title("Add / Update Employee"));val id=edit("Employee ID e.g. PV002");val n=edit("Employee Name");val p=edit("Password",true);val sal=edit("Monthly Salary");sal.inputType=InputType.TYPE_CLASS_NUMBER;v.addView(id);v.addView(n);v.addView(p);v.addView(sal);v.addView(button("SAVE EMPLOYEE"){val e=id.text.toString().trim().uppercase(Locale.getDefault());if(e.isBlank()||n.text.toString().isBlank()||p.text.toString().isBlank())Toast.makeText(this,"ID, Name and Password required",Toast.LENGTH_SHORT).show() else if(!prefs.contains("emp_${e}_pass")&&employeeIds().size>=10)Toast.makeText(this,"Maximum 10 employees allowed",Toast.LENGTH_SHORT).show() else {prefs.edit().putString("emp_${e}_name",n.text.toString().trim()).putString("emp_${e}_pass",p.text.toString()).putString("emp_${e}_salary",sal.text.toString().ifBlank{"0"}).apply();Toast.makeText(this,"Employee saved",Toast.LENGTH_SHORT).show();showAdminDashboard()}});v.addView(button("BACK"){showAdminDashboard()})}
    private fun showEmployeeList(){val v=base();v.addView(title("Employee List"));employeeIds().forEach{id->v.addView(label("$id - ${prefs.getString("emp_${id}_name","")} | Salary ₹${prefs.getString("emp_${id}_salary","0")}"));if(id!="PV001")v.addView(button("DELETE $id"){prefs.edit().remove("emp_${id}_name").remove("emp_${id}_pass").remove("emp_${id}_salary").apply();Toast.makeText(this,"$id deleted",Toast.LENGTH_SHORT).show();showEmployeeList()})};v.addView(button("BACK"){showAdminDashboard()})}
    private fun today()=SimpleDateFormat("yyyy-MM-dd",Locale.getDefault()).format(Date())
    private fun showEmployeeDashboard(){val v=base();val name=prefs.getString("emp_${currentEmployee}_name",currentEmployee);v.addView(title("Employee Dashboard"));v.addView(label("$name ($currentEmployee)"));v.addView(label("Location verification: will be added later"));val status=label("");fun refresh(){val d=today();val i=prefs.getString("in_${currentEmployee}_$d",null);val o=prefs.getString("out_${currentEmployee}_$d",null);val im=prefs.getLong("inms_${currentEmployee}_$d",0);val om=prefs.getLong("outms_${currentEmployee}_$d",0);val worked=if(im>0&&om>=im){val m=(om-im)/60000;"${m/60}h ${m%60}m"}else "-";status.text="Today\nIN: ${i?:"Not marked"}\nOUT: ${o?:"Not marked"}\nWORKED: $worked"};v.addView(status);refresh();v.addView(button("CHECK IN"){val d=today();if(prefs.contains("in_${currentEmployee}_$d"))Toast.makeText(this,"Check-in already marked",Toast.LENGTH_SHORT).show() else {val t=SimpleDateFormat("hh:mm a",Locale.getDefault()).format(Date());prefs.edit().putString("in_${currentEmployee}_$d",t).putLong("inms_${currentEmployee}_$d",System.currentTimeMillis()).apply();refresh()}});v.addView(space());v.addView(button("CHECK OUT"){val d=today();if(!prefs.contains("in_${currentEmployee}_$d"))Toast.makeText(this,"Check in first",Toast.LENGTH_SHORT).show() else if(prefs.contains("out_${currentEmployee}_$d"))Toast.makeText(this,"Check-out already marked",Toast.LENGTH_SHORT).show() else {val t=SimpleDateFormat("hh:mm a",Locale.getDefault()).format(Date());prefs.edit().putString("out_${currentEmployee}_$d",t).putLong("outms_${currentEmployee}_$d",System.currentTimeMillis()).apply();refresh()}});v.addView(space());v.addView(button("ATTENDANCE HISTORY"){showEmployeeHistory()});v.addView(space());v.addView(button("SALARY DETAILS"){showSalary()});v.addView(space());v.addView(button("LEAVE REQUEST"){showLeaveRequest()});v.addView(space());v.addView(button("LOGOUT"){showRoleScreen()})}
    private fun showLeaveRequest(){val v=base();v.addView(title("Leave Request"));val date=edit("Leave date e.g. 10-09-2026");val reason=edit("Reason");v.addView(date);v.addView(reason);v.addView(button("SUBMIT REQUEST"){if(date.text.toString().isBlank()||reason.text.toString().isBlank())Toast.makeText(this,"Date and reason required",Toast.LENGTH_SHORT).show() else {val key="leave_${currentEmployee}_${System.currentTimeMillis()}";prefs.edit().putString(key,"${date.text}|${reason.text}|PENDING").apply();Toast.makeText(this,"Leave request submitted",Toast.LENGTH_SHORT).show();showEmployeeDashboard()}});v.addView(button("BACK"){showEmployeeDashboard()})}
    private fun leaveKeys()=prefs.all.keys.filter{it.startsWith("leave_")}.sortedDescending()
    private fun showAdminLeaves(){val v=base();v.addView(title("Leave Requests"));if(leaveKeys().isEmpty())v.addView(label("No leave requests"));leaveKeys().forEach{k->val parts=(prefs.getString(k,"")?:"").split("|");val id=k.removePrefix("leave_").substringBefore("_");val date=parts.getOrElse(0){""};val reason=parts.getOrElse(1){""};val st=parts.getOrElse(2){"PENDING"};v.addView(label("$id - ${prefs.getString("emp_${id}_name",id)}\nDate: $date\nReason: $reason\nStatus: $st"));if(st=="PENDING"){v.addView(button("APPROVE"){prefs.edit().putString(k,"$date|$reason|APPROVED").apply();showAdminLeaves()});v.addView(button("REJECT"){prefs.edit().putString(k,"$date|$reason|REJECTED").apply();showAdminLeaves()})}};v.addView(button("BACK"){showAdminDashboard()})}
    private fun showEmployeeHistory(){val v=base();v.addView(title("Attendance History"));val df=SimpleDateFormat("yyyy-MM-dd",Locale.getDefault());val ds=SimpleDateFormat("dd MMM yyyy",Locale.getDefault());val cal=Calendar.getInstance();repeat(30){val k=df.format(cal.time);val i=prefs.getString("in_${currentEmployee}_$k",null);val o=prefs.getString("out_${currentEmployee}_$k",null);if(i!=null||o!=null){val im=prefs.getLong("inms_${currentEmployee}_$k",0);val om=prefs.getLong("outms_${currentEmployee}_$k",0);val w=if(im>0&&om>=im){val m=(om-im)/60000;"${m/60}h ${m%60}m"}else "-";v.addView(label("${ds.format(cal.time)}\nIN: ${i?:"-"} OUT: ${o?:"-"}\nWorked: $w"))};cal.add(Calendar.DAY_OF_YEAR,-1)};v.addView(button("BACK"){showEmployeeDashboard()})}
    private fun showSalary(){val v=base();v.addView(title("Salary Details"));v.addView(label("Employee: $currentEmployee\nMonthly Salary: ₹${prefs.getString("emp_${currentEmployee}_salary","0")}"));v.addView(button("BACK"){showEmployeeDashboard()})}
    private fun showAdminAttendance(){val v=base();v.addView(title("Attendance Overview"));val d=today();employeeIds().forEach{id->val im=prefs.getLong("inms_${id}_$d",0);val om=prefs.getLong("outms_${id}_$d",0);val w=if(im>0&&om>=im){val m=(om-im)/60000;"${m/60}h ${m%60}m"}else "-";v.addView(label("$id - ${prefs.getString("emp_${id}_name","")}\nIN: ${prefs.getString("in_${id}_$d",null)?:"-"} OUT: ${prefs.getString("out_${id}_$d",null)?:"-"}\nWORKED: $w"))};v.addView(button("BACK"){showAdminDashboard()})}
}
